  const row = dateNode.closest('div');
  const parent = dateNode.parentElement;
  const rowHtml = row ? row.outerHTML.slice(0, 4000) : null;
  const svgs = [];
  const searchRoot = parent?.parentElement || parent || document.body;
  searchRoot.querySelectorAll('svg').forEach((svg, index) => {
    const cs = getComputedStyle(svg);
    svgs.push({
      index,
      className: svg.getAttribute('class'),
      viewBox: svg.getAttribute('viewBox'),
      width: svg.getAttribute('width'),
      height: svg.getAttribute('height'),
      fill: svg.getAttribute('fill'),
      stroke: svg.getAttribute('stroke'),
      strokeWidth: svg.getAttribute('stroke-width'),
      computedWidth: cs.width,
      computedHeight: cs.height,
      computedColor: cs.color,
      computedFill: cs.fill,
      computedStroke: cs.stroke,
      computedStrokeWidth: cs.strokeWidth,
      outerHTML: svg.outerHTML,
    });
  });
  const nearbySvgs = [];
  document.querySelectorAll('svg').forEach((svg) => {
    const text = svg.parentElement?.textContent?.trim() || '';
    if (text.includes('2026-08-14') || text.includes('17:38')) {
      nearbySvgs.push({
        parentTag: svg.parentElement?.tagName,
        parentClass: svg.parentElement?.className,
        parentText: text.slice(0, 80),
        outerHTML: svg.outerHTML,
        className: svg.getAttribute('class'),
        viewBox: svg.getAttribute('viewBox'),
      });
    }
  });
  return {
    dateParentClass: parent?.className,
    dateParentHTML: parent?.outerHTML?.slice(0, 2000),
    rowClass: row?.className,
    svgs,
    nearbySvgs,
  };
}

