  const dateEl = Array.from(document.querySelectorAll('span')).find(el => el.textContent.trim() === '2026-08-14');
  if (!dateEl) return { error: 'not found' };
  dateEl.scrollIntoView({ block: 'center' });
  const wrap = dateEl.parentElement;
  const row = wrap?.parentElement;
  const r = (el) => {
    const b = el.getBoundingClientRect();
    return { x: b.x, y: b.y, w: b.width, h: b.height };
  };
  return {
    wrap: wrap?.outerHTML,
    wrapBox: wrap ? r(wrap) : null,
    rowBox: row ? r(row) : null,
    svg: wrap?.querySelector('svg')?.outerHTML,
  };
}
